import{_ as s,a0 as a,w as p,s as d,ao as u,I as r,x as n,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary” | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary” | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary” | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141029 Linux FAQs with Answers--How to fix hda-duplex not supported in this QEMU binary","title":"Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary”","tag":"201411","desc":""},"relativePath":"201411/20141029 Linux FAQs with Answers--How to fix hda-duplex not supported in this QEMU binary.md","filePath":"[post].md"}'),l={name:"201411/20141029 Linux FAQs with Answers--How to fix hda-duplex not supported in this QEMU binary.md"};function h(x,t,m,g,f,b){const e=a("Link");return p(),d("div",null,[t[11]||(t[11]=u(`<h1 id="linux-有問必答-如何修復-hda-duplex-not-supported-in-this-qemu-binary" tabindex="-1">Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary” <a class="header-anchor" href="#linux-有問必答-如何修復-hda-duplex-not-supported-in-this-qemu-binary" aria-label="Permalink to “Linux 有問必答：如何修復“hda-duplex not supported in this QEMU binary””">​</a></h1><blockquote><p><strong>提問</strong>： 當我嘗試在虛擬機中安裝一個新的Linux時，虛擬機不能啓動且報了下面這個錯誤：&quot;unsupported configuration: hda-duplex not supported in this QEMU binary.&quot;（“不支持的配置：hda-duplex在此QEMU文件中不支持。”） 我該如何修復？</p></blockquote><p>這個錯誤可能來自一個當默認聲卡型號不能被識別時的一個qemu bug。</p><p><img src="https://farm4.staticflickr.com/3935/15000012754_b8b147fb16_o.png" alt=""></p><pre><code>無法完成安裝：‘不支持的配置：hda-duplex在此QEMU文件中不支持’
</code></pre><p>要解決這個問題，按照下面的做。</p><h3 id="方案一-virt-manager" tabindex="-1">方案一: virt-manager <a class="header-anchor" href="#方案一-virt-manager" aria-label="Permalink to “方案一: virt-manager”">​</a></h3><p>在<strong>virt-manager</strong>中，打開虛擬機的虛擬硬件詳細菜單，進入聲卡選項，改變默認的設備型號為ac97。</p><p><img src="https://farm4.staticflickr.com/3956/15435183020_d97856170c_z.jpg" alt=""></p><p>點擊“應用”按鈕並保存設置。看一下虛擬機現在是否可以啓動了。</p><h3 id="方案二-virsh" tabindex="-1">方案二: Virsh <a class="header-anchor" href="#方案二-virsh" aria-label="Permalink to “方案二: Virsh”">​</a></h3><p>如果你使用的是<strong>virsh</strong> 而不是<strong>virt-manager</strong>， 你可以編輯VM相應的配置文件。在<code>&lt;device&gt;</code>節點中查找<strong>sound</strong>節點，並按照下面的默認聲卡型號改成<strong>ac97</strong>。</p><pre><code>&lt;devices&gt;
  . . .
  &lt;sound model=&#39;ac97&#39;&gt;
    &lt;address type=&#39;pci&#39; domain=&#39;0x0000&#39; bus=&#39;0x00&#39; slot=&#39;0x04&#39; function=&#39;0x0&#39;/&gt;
  &lt;/sound&gt;
  . . .
&lt;/device&gt;
</code></pre><hr>`,14)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),i(e,{href:"http://ask.xmodulo.com/hda-duplex-not-supported-in-this-qemu-binary.html"},{default:o(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/hda-duplex-not-supported-in-this-qemu-binary.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=n("譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const y=s(l,[["render",h]]);export{L as __pageData,y as default};
